def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    depreciation_rate = change / v1

    return {
        "value": depreciation_rate,
        "trace": {
            "initial_rate": v1,
            "final_rate": v2,
            "change": change,
            "depreciation_rate": depreciation_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "比例"
            }
        }
    }
